import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Customer Portal Guide: Overview","description":"","frontmatter":{},"headers":[],"relativePath":"client/overview.md","filePath":"client/overview.md"}'),r={name:"client/overview.md"};function o(s,e,l,c,g,d){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="customer-portal-guide-overview" tabindex="-1">Customer Portal Guide: Overview <a class="header-anchor" href="#customer-portal-guide-overview" aria-label="Permalink to &quot;Customer Portal Guide: Overview&quot;">​</a></h1><p>The FOSSBilling Customer Portal (<code>http://localhost:3001</code>) gives clients a modern, responsive, and seamless interface to browse hosting plans, register domains, pay invoices, manage cloud services, and get technical assistance.</p><div class="tip custom-block"><p class="custom-block-title">Detailed Step-by-Step Purchasing Walkthrough</p><p>For a complete visual flowchart and purchasing walkthrough, visit the <strong><a href="/guide/step-by-step-guide#phase-5-client-ordering-purchasing-journey">Complete Step-by-Step Usage Guide</a></strong>.</p></div><hr><h2 id="🚶-the-customer-journey-step-by-step" tabindex="-1">🚶 The Customer Journey: Step-by-Step <a class="header-anchor" href="#🚶-the-customer-journey-step-by-step" aria-label="Permalink to &quot;🚶 The Customer Journey: Step-by-Step&quot;">​</a></h2><h3 id="_1-registration-security-onboarding" tabindex="-1">1. Registration &amp; Security Onboarding <a class="header-anchor" href="#_1-registration-security-onboarding" aria-label="Permalink to &quot;1. Registration &amp; Security Onboarding&quot;">​</a></h3><ul><li>Visit the portal and click <strong>Register</strong> or sign up directly during the checkout flow.</li><li>Built-in honeypot algorithms and disposable email filters protect against automated bots without annoying captchas.</li><li>Set currency preference and toggle interface language (with automatic RTL support for Arabic/Hebrew).</li></ul><h3 id="_2-browsing-ordering-services" tabindex="-1">2. Browsing &amp; Ordering Services <a class="header-anchor" href="#_2-browsing-ordering-services" aria-label="Permalink to &quot;2. Browsing &amp; Ordering Services&quot;">​</a></h3><ul><li><strong><a href="/client/storefront">Storefront &amp; Ordering</a>:</strong> Browse categorized hosting plans, VPS, and cloud packages.</li><li><strong>Domain Availability Checker:</strong> Real-time lookup for <code>.com</code>, <code>.net</code>, <code>.io</code>, and regional TLDs. Choose between new registration, registrar transfer, or bringing your own domain.</li><li><strong>Dynamic Configuration Forms:</strong> Configure server hostnames, root passwords, OS distribution (Ubuntu, Debian, AlmaLinux), and optional add-ons.</li></ul><h3 id="_3-reviewing-cart-applying-discounts" tabindex="-1">3. Reviewing Cart &amp; Applying Discounts <a class="header-anchor" href="#_3-reviewing-cart-applying-discounts" aria-label="Permalink to &quot;3. Reviewing Cart &amp; Applying Discounts&quot;">​</a></h3><ul><li>Inspect itemized shopping cart items with taxes and discounts applied in real time.</li><li>Enter promotional coupon codes (e.g. <code>PROMO10</code>).</li><li>Seamless checkout in 1 click.</li></ul><h3 id="_4-paying-invoices-managing-funds" tabindex="-1">4. Paying Invoices &amp; Managing Funds <a class="header-anchor" href="#_4-paying-invoices-managing-funds" aria-label="Permalink to &quot;4. Paying Invoices &amp; Managing Funds&quot;">​</a></h3><ul><li><strong><a href="/client/invoices">Invoices &amp; Payments</a>:</strong> Instant payment via Credit/Debit Cards (Stripe), PayPal, Midtrans QRIS/Virtual Accounts, or Bank Wire.</li><li><strong>Prepay Deposits:</strong> Add funds in advance so recurring subscription invoices are settled automatically without service disruption.</li><li><strong>Tax Invoices &amp; Receipts:</strong> Download official, signed PDF invoices with tax breakdown.</li></ul><h3 id="_5-managing-active-services-single-sign-on-sso" tabindex="-1">5. Managing Active Services &amp; Single Sign-On (SSO) <a class="header-anchor" href="#_5-managing-active-services-single-sign-on-sso" aria-label="Permalink to &quot;5. Managing Active Services &amp; Single Sign-On (SSO)&quot;">​</a></h3><ul><li><strong><a href="/client/licenses-downloads">Licenses &amp; Downloads</a>:</strong> View server IP addresses, nameservers, disk/bandwidth stats, and reset license bindings.</li><li><strong>Control Panel SSO:</strong> 1-Click login directly into cPanel, HestiaCP, or Plesk without typing credentials.</li></ul><h3 id="_6-submitting-support-tickets-getting-help" tabindex="-1">6. Submitting Support Tickets &amp; Getting Help <a class="header-anchor" href="#_6-submitting-support-tickets-getting-help" aria-label="Permalink to &quot;6. Submitting Support Tickets &amp; Getting Help&quot;">​</a></h3><ul><li><strong><a href="/client/support">Helpdesk &amp; Support</a>:</strong> Open tickets with departments (Technical, Billing, Sales), set urgency, attach logs/screenshots, and receive real-time updates.</li></ul>',17)])])}const h=i(r,[["render",o]]);export{p as __pageData,h as default};
